import{Z as t,e as o,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"Zapier","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/zapier.md","filePath":"integrations/automations/zapier.md","lastUpdated":1780377007000}'),i={name:"integrations/automations/zapier.md"};function r(s,e,l,h,p,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="zapier" tabindex="-1">Zapier <a class="header-anchor" href="#zapier" aria-label="Permalink to &quot;Zapier&quot;">​</a></h1><p>Connect Zapier to pass submitted answers to an automated workflow. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Zapier</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-zapier-api" tabindex="-1">Step 2. Connect to the Zapier API <a class="header-anchor" href="#step-2-connect-to-the-zapier-api" aria-label="Permalink to &quot;Step 2. Connect to the Zapier API&quot;">​</a></h3><ol><li>Go to <a href="https://zapier.com/app/zaps" target="_blank">Zapier</a> and create a new Zap.</li><li>For the <strong>Choose App &amp; Event</strong> value, enter <strong>Webhooks by Zapier</strong>.</li><li>For the <strong>Choose Trigger Event</strong> value, enter <strong>Catch Hook</strong>.</li><li>Click <strong>Continue</strong>.</li><li>Copy the <strong>Custom Webhook URL</strong> into the <strong>Webhook</strong> field in Formie.</li></ol><h3 id="step-3-form-setting-test-payload" tabindex="-1">Step 3. Form Setting &amp; Test Payload <a class="header-anchor" href="#step-3-form-setting-test-payload" aria-label="Permalink to &quot;Step 3. Form Setting &amp; Test Payload&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination workflow or URL supported by this integration and map the submitted values it needs. Use a test destination while checking the connection.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Inspect the receiving workflow’s run history or request log. Check both the received values and the outcome of any following steps.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',11)])])}const m=t(i,[["render",r]]);export{d as __pageData,m as default};
